// AUTO-GENERATED brand assets — do not hand-edit the data URIs.
// Source: design/solar_flow_full_logo_dark.png (logo, downscaled to 480px wide) and
// design/solar_flow_symbol_1024.png (app symbol, 512x512). Regenerate via the scratchpad gen_brand.py.
//
// WHY base64-in-TS (not an import or public/ file): the build is vite-plugin-singlefile and
// tools/privacy-check.mjs forbids (a) any dist/ file other than the two HTML bundles — so no public/
// icons; (b) bundling anything outside src/*.{ts,js,css} + node_modules — so no `import logo.png`;
// (c) any data:application/* inlined in the HTML — so the PWA manifest is built at RUNTIME as a blob
// (its data: icons live inside the blob, never in the static HTML). data:image/* IS allowed, so these
// constants pass the privacy check, and installAppIcons() wires favicon + apple-touch-icon + manifest.

/** Full brand logo (dark-teal tile, light wordmark + amber accent) — legible on the green sidebar. */
export const LOGO_DARK = 'data:image/png;base64,'

/** Square app symbol (transparent) — used for the favicon, apple-touch-icon, and PWA manifest icons. */
export const APP_ICON = 'data:image/png;base64,'

const GREEN = '#17594a'

/**
 * Inject the installed-app icon set at runtime: browser favicon, iOS apple-touch-icon (home-screen), and
 * a Web App Manifest. The manifest is assembled here and handed to the browser as a blob: URL so no
 * `data:application/manifest+json` ever appears in the single-file HTML (the privacy check forbids that);
 * the icon entries are data:image/png inside the blob. The build CSP adds `manifest-src blob:` so the
 * served (demo) build can load it. Idempotent-ish: safe to call once at startup.
 */
export function installAppIcons(): void {
  const head = document.head
  const addLink = (rel: string, href: string, extra?: Record<string, string>) => {
    const l = document.createElement('link')
    l.rel = rel
    l.href = href
    if (extra) for (const [k, v] of Object.entries(extra)) l.setAttribute(k, v)
    head.appendChild(l)
  }

  // Favicon (browser tab) + Apple touch icon (iOS "Add to Home Screen").
  addLink('icon', APP_ICON, { type: 'image/png' })
  addLink('apple-touch-icon', APP_ICON)

  // Web App Manifest — built at runtime, served as a blob so it stays out of the static HTML.
  const manifest = {
    name: 'Solar Management Dashboard',
    short_name: 'Solar Dashboard',
    start_url: '.',
    scope: '.',
    display: 'standalone',
    background_color: '#ffffff',
    theme_color: GREEN,
    icons: [
      { src: APP_ICON, sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: APP_ICON, sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: APP_ICON, sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  }
  try {
    const blob = new Blob([JSON.stringify(manifest)], { type: 'application/manifest+json' })
    addLink('manifest', URL.createObjectURL(blob))
  } catch {
    // Blob/URL unavailable (very old engine): favicon + apple-touch-icon above still cover the icon.
  }
}
